package seed

import (
	"github.com/xdanny/hyperplane-workflows/internal/sdkworkflow"
	"github.com/xdanny/hyperplane-workflows/internal/store"
)

func reconciliationTemplate() store.WorkflowTemplate {
	return sdkNodeTemplate("dashboard-reconciliation", "Measure two sources, approve their accounting equations, and explain discrepancies with exact per-segment arithmetic. Edit and run every step through the SDK.", "Reconcile these sources without modifying either one.\nQuestion to answer: {slot:question}\nDashboard figures to reproduce first: {slot:dashboardFigures}\nReporting period/calendar: {slot:period}\nSource A: {slot:sourceA}\nSource B: {slot:sourceB}\nShared grain: {slot:sharedGrain}\nKey columns: {slot:keyColumns}\nMeasure definitions: {slot:measures}\nOwner tolerances and units: {slot:tolerances}\nKnown differences: {slot:knownDifferences}\nSafe use: {slot:safeUse}\nRuntime budget: {slot:runtimeBudget}\nHandover: {slot:handover}\nBlank optional inputs mean unspecified. Configure source connections and temporary tool setup explicitly on the profile and audit steps when needed. Prose grants neither. Keep outputs local; do not send or publish.",
		[]store.ContextSlot{
			{
				// The question the meeting will actually ask. Without it the
				// sealed report cannot be checked against the thing it was
				// commissioned to answer — and the recipe cannot know it must
				// first reproduce the number the room already has.
				ID:       "question",
				Label:    "The question this has to answer, as the meeting will ask it",
				Hint:     "In the words it will be asked in, not in the platform's. It is what the finished report is checked against, and it is the difference between \"the two sources differ by $84,201.55 in enterprise\" and an answer nobody asked for.",
				Required: true,
				Example:  "why did Q2 revenue drop 4% against the Finance dashboard?",
			},
			{
				ID:       "dashboardFigures",
				Label:    "What each dashboard shows today",
				Hint:     "The number on the screen right now, per dashboard, with the date it is as of and where you read it. The reconciliation reproduces these first — a run that cannot get back to the figure in the room has not started explaining it yet.",
				Required: false,
				Type:     store.SlotTypeTable,
				Columns: []store.SlotColumn{
					{ID: "dashboard", Label: "Dashboard", Hint: "Which dashboard this figure is on.", Required: true},
					{ID: "figure", Label: "Figure today", Hint: "The number as displayed, at full precision if you have it.", Required: true},
					{ID: "asOf", Label: "As of", Hint: "The date or timestamp the figure covers — two figures as of different days are not a disagreement."},
					{ID: "link", Label: "Link", Hint: "Where you read it. A URL or a screenshot path."},
				},
				Example: `[{"dashboard":"Finance revenue (Looker)","figure":"84201.55","asOf":"2026-07-01","link":"https://looker.internal/dashboards/12"}]`,
			},
			{
				ID:       "period",
				Label:    "Reporting period and calendar",
				Hint:     "Which period this covers, and whose calendar it is: fiscal or calendar quarter, the timezone the dates are in, and the day any snapshot is cut on. \"Q2\" means at least three different windows depending on those answers.",
				Required: false,
				Example:  "fiscal Q2 FY26 (Apr 1 – Jun 30), dates in America/New_York, CRM snapshot cut on the 15th",
			},
			{
				ID:       "sourceA",
				Audience: store.SlotAudienceEngineer,
				Label:    "Dashboard A — what it is, who owns it, and the table or export behind it",
				Hint:     "The table, file or export the first dashboard actually reads — where it lives, the period it covers, its size, and how to read it (the query, the view, the export). \"The finance dashboard\" is not a source: the source is the thing a query can be pointed at, and a reconciliation that cannot name it is reconciling two beliefs.",
				Required: true,
				Example:  "postgres analytics.revenue_daily (~1.4M rows, 2025-01-01 → 2025-06-30), read directly with SQL at invoice-line level",
			},
			{
				ID:       "sourceB",
				Audience: store.SlotAudienceEngineer,
				Label:    "Dashboard B — what it is, who owns it, and the table or export behind it",
				Hint:     "The same detail for the second dashboard. If B can be read by a path that does not go through A's loader, say so — two numbers derived through one transform agree by construction, which proves nothing about the dashboards.",
				Required: true,
				Example:  "exports/salesforce_opportunities_2025H1.csv (~186k closed-won rows), parsed independently with duckdb rather than through the warehouse loader",
			},
			{
				ID:       "sharedGrain",
				Label:    "One row = …",
				Hint:     "What ONE row means once each side is rolled up — finish the sentence: \"one row per close_date per region\". Totals compared across two different grains are not a disagreement, they are a category error, and this is the line that stops one being presented as the other. The columns that identify that row go in Key columns below, not here.",
				Required: true,
				Audience: store.SlotAudienceEngineer,
				Example:  "one row per close_date per region per product_line; the CRM export is at opportunity level and must be aggregated up to it",
			},
			{
				ID:       "keyColumns",
				Label:    "Key columns",
				Hint:     "The columns that identify one row once BOTH sides are rolled up to that shared grain — the columns the two sides are joined on before any total is compared. If this data has no natural key — no set of columns guaranteed to be unique — write `none` first and then the closest candidate columns (`none, VendorID, pickup_time, PULocationID`). That is a real answer, not a blank: the workflow treats the candidates as the closest thing to a key and reports whether it actually holds.",
				Required: true,
				Type:     store.SlotTypeList,
				Audience: store.SlotAudienceEngineer,
				Example:  "close_date, region, product_line",
			},
			{
				ID:       "measures",
				Label:    "Measures",
				Hint:     "One row per number that must match, with what it means on EACH side — what is summed or counted, over which rows, after which adjustments. Two sides that define \"revenue\" differently do not have a discrepancy, they have two measures, and naming both definitions up front is what keeps a vocabulary difference from being reported as a gap in the data.",
				Required: true,
				Type:     store.SlotTypeTable,
				Columns: []store.SlotColumn{
					{ID: "measure", Label: "Measure", Hint: "The name you would say in the meeting.", Required: true},
					{ID: "definitionA", Label: "Definition in A", Hint: "What dashboard A sums or counts, over which rows, after which adjustments.", Required: true},
					{ID: "definitionB", Label: "Definition in B", Hint: "The same, for dashboard B. If the two sentences differ, that difference is the finding.", Required: true},
				},
				Example: `[{"measure":"net_revenue","definitionA":"Finance: sum(amount_usd) after refunds","definitionB":"Sales: sum(Amount) on closed-won, before refunds"},{"measure":"closed_deals","definitionA":"Finance: distinct invoiced orders","definitionB":"Sales: closed-won opportunities"}]`,
			},
			{
				// S-9: this was one textarea carrying absolute, relative, exact
				// and per-segment numbers at once — so "0.5%" and "$1,000" were
				// the same string to the platform, and the denominator of a
				// relative tolerance was never asked for at all.
				ID:       "tolerances",
				Label:    "Tolerance per measure",
				Hint:     "How close counts as agreement, per measure, declared now — before any total exists. The unit is the part that was missing: 0.5% of WHICH side's total is a different number from 0.5% of the other's. A tolerance set afterwards to sit just above the gap that appeared defends nothing in a meeting, and the workflow rejects one.",
				Required: true,
				Type:     store.SlotTypeTable,
				Columns: []store.SlotColumn{
					{ID: "measure", Label: "Measure", Hint: "One of the measures above.", Required: true},
					{ID: "unit", Label: "Unit", Hint: "% of A total, % of B total, an absolute currency amount, a count, or exact match.", Required: true,
						Options: []string{"percent_of_a", "percent_of_b", "absolute", "count", "exact"}},
					{ID: "value", Label: "Value", Hint: "The number itself. Use 0 when the unit is `exact`.", Required: true},
					{ID: "segmentValue", Label: "Per-segment value", Hint: "Optional per-segment value. Set its unit explicitly in the next field; the percentage denominator is local to each segment."},
					{ID: "segmentUnit", Label: "Per-segment unit", Hint: "Required with a per-segment value.", Options: []string{"percent_of_a", "percent_of_b", "absolute", "count", "exact"}},
					{ID: "setBy", Label: "Set by", Hint: "Who stands behind this number, and when they set it."},
				},
				Example: `[{"measure":"net_revenue","unit":"percent_of_a","value":"0.05","segmentValue":"250","segmentUnit":"absolute","setBy":"Sofia, 2026-08-21"},{"measure":"closed_deals","unit":"exact","value":"0","setBy":"Sofia, 2026-08-21"}]`,
			},
			{
				ID:       "knownDifferences",
				Label:    "Known differences",
				Hint:     "Every filter one side applies and the other does not — test accounts, intercompany rows, a snapshot cut-off, refunds netted on one side only. Each becomes a NAMED term of the accounting equation. Anything you do not name here that turns out to matter is not a term: it is reported as unexplained, which is exactly where you want it.",
				Required: false,
				Type:     store.SlotTypeTable,
				Columns: []store.SlotColumn{
					{ID: "name", Label: "Name", Hint: "What you call this difference.", Required: true},
					{ID: "side", Label: "Which side applies it", Hint: "A, B, or both.", Required: true, Options: []string{"A", "B", "both"}},
					{ID: "filter", Label: "The filter, if you know it", Hint: "The predicate that selects those rows. A term with no predicate cannot be a term — it is reported as unexplained."},
					{ID: "owner", Label: "Who owns it", Hint: "Who to ask when this difference turns out to be the answer."},
				},
				Example: `[{"name":"internal test accounts","side":"A","filter":"account_type = 'test'","owner":"Finance ops"},{"name":"CRM snapshot cut-off","side":"B","filter":"close_date <= snapshot_day","owner":"Sales ops"}]`,
			},
			{
				ID:       "safeUse",
				Label:    "What is confidential here, and what these numbers must not be used for",
				Hint:     "Sensitive columns and how they may appear as a segment label or an example row in the delta table, and what these numbers must NOT be used for.",
				Required: true,
				Example:  "customer names are PII: segments as region and product_line only, examples as opportunity id + amount; for reconciling the dashboards, not for revising quota attainment",
			},
			{
				ID:       "runtimeBudget",
				Label:    "Deadline / maximum runtime",
				Hint:     "How long the whole reconciliation may take before it should fail loudly rather than grind on. Leave empty to use the application run limit. A supplied check duration must be enforced by the generated checks, not met by silently sampling. The application also enforces its separate total run deadline, including approval waits.",
				Required: false,
				Example:  "the whole reconciliation must finish inside 20 minutes; fail loudly rather than reconcile a sample in silence",
			},
			handoverSlot("report", "a one-page markdown summary plus the per-segment CSV, to #finance-analytics"),
		},
		sdkworkflow.Node{ID: "profile", Kind: "task", Title: "Measure both sources", Instruction: "Measure both declared sources independently at the shared grain. Capture source identity, duplicate counts, measure totals and uncertainty without modifying either source. Follow the built-in source profile contract.", Acceptance: "reconciliation-profile", Inputs: map[string]string{"sourceA": "{slot:sourceA}", "sourceB": "{slot:sourceB}", "sharedGrain": "{slot:sharedGrain}", "keyColumns": "{slot:keyColumns}", "measures": "{slot:measures}", "tolerances": "{slot:tolerances}", "knownDifferences": "{slot:knownDifferences}"}},
		sdkworkflow.Node{ID: "profile-review", Kind: "check", Title: "Review comparability and measured totals", Instruction: "     BOTH sources are profiled with MEASURED numbers at the SHARED GRAIN: each carries a row count on the order of its declared size, the row count after roll-up to that grain, the period it actually covers observed from the data, and a scan mode. EVERY measure named in the brief appears exactly once in measures[] with a total for BOTH sides at full precision and the rows entering each total — a measure totalled on one side alone, or listed with a null total on the other, is a fail, and so is a measure the brief named that is missing entirely. GRAIN UNIQUENESS is reported for both sides with a duplicate-key count; a profile that compares totals without ever checking that the declared key is unique on each side is a fail, because a duplicated key silently multiplies one side. KEY COVERAGE is reported — keys only in A, only in B, and in both, each with the amount they carry. The segment vocabulary names values present on one side and absent from the other. Read paths are stated, and where both sides were read through the same transform that is named as such rather than left implicit. Any measure whose two definitions are not commensurable (different currency with no declared rate, different time basis, different denominator) is flagged commensurable:false rather than left to surface later as an unexplained delta. Fail on placeholders, TODOs, round figures with no measurement behind them, totals reasoned from column names instead of the data, or a sample scan that does not state its size and method for BOTH sides. If any column named sensitive in the safe-use boundary appears with raw values rather than the handling that boundary permits, fail. Include the most consequential finding for the business in findings. Every count carries its denominator in plain words."},
		sdkworkflow.Node{ID: "rules", Kind: "task", Title: "Propose accounting equations", Instruction: "Propose accounting equations from the measured sources with executable signed filters, exact owner tolerances and a complete segment plan. Follow the built-in rules contract; do not execute before approval.", Acceptance: "reconciliation-rules"},
		sdkworkflow.Node{ID: "rules-review", Kind: "check", Title: "Review equations and declared tolerances", Instruction: "    EVERY measure named in the brief is either an equation in equations[] or an entry in unexpressible[] with a reason — a measure that appears in neither is a silently dropped promise and a fail. Every equation is a real accounting identity: totalA, totalB and observedDelta come from the profile, and the terms plus the unexplained remainder are structurally capable of reconstructing observedDelta. EVERY TERM IS A NAMED FILTER WITH AN EXECUTABLE PREDICATE over columns that exist in the profile: a term called `other`, `timing`, `misc`, `rounding` or `definitional differences` with no predicate that selects rows is a residual bucket masquerading as an explanation — automatic fail. Every term states the side that applies it and whether it came from the owner's declared exclusions or from the profile. A SEGMENT PLAN exists, naming the breakdown dimension and requiring per-segment deltas to sum to the total delta. A GRAIN UNIQUENESS precondition exists for both sides. Every tolerance states where it came from, and every severity names a concrete consequence — which report or decision is wrong if this measure does not reconcile — rather than restating the equation. Preserve the exact owner tolerance even when it exceeds the measured discrepancy. Do not invent a replacement threshold to obtain agreement. Mark expectedToBalance from the measured evidence. A measure whose definitions differ between the sides must be treated as a definitional difference — unexpressible, or a term that names it — never reported as a discrepancy in the data. Include the most consequential finding for the business in findings. Every count carries its denominator in plain words. EVERY equation carries toleranceOrigin, and \"declared\" is only honest when the number AND the unit are exactly the ones on that measure's own tolerance row in the brief — a tolerance borrowed from another measure, restated in a different denominator (percent_of_a where the owner wrote percent_of_b), or marked declared with no row behind it, is a FAIL.\nOwner tolerances remain valid even near the measured gap; reject substitutions, not legitimate owner choices. Additional profile-derived filters need explicit predicates and visible source attribution. Segment values need explicit units. Equations cover only declared measures."},
		sdkworkflow.Node{ID: "approve-rules", Kind: "approval", Title: "Approve equations, filters and tolerances", Instruction: "Review recon-rules.json and the measured profiles. Confirm both measure definitions, every named filter (including profile-derived additions), the exact owner tolerances and explicit segment units before execution. Controls are model-authored test copies and must disclose that origin."},
		sdkworkflow.Node{ID: "audit", Kind: "task", Title: "Execute approved reconciliation", Instruction: "Execute the approved reconciliation equations and segment checks against the measured sources. Preserve exact amounts, owner tolerances and opposing segment gaps. Prove the same equations detect the copied negative cases. Follow the built-in report contract.", Acceptance: "reconciliation-audit"},
		sdkworkflow.Node{ID: "audit-review", Kind: "check", Title: "Review identities, segments and controls", Instruction: "    EVERY approved equation appears exactly once, either in measures[] with executed results or in notRun[] with a concrete reason — an equation that appears in neither is a silent drop and an automatic fail, and notRun is a failure of the reconciliation rather than a neutral note. THE ACCOUNTING MUST BALANCE ARITHMETICALLY: for every measure, recompute observedDelta minus the signed sum of the term amounts and check it equals the reported unexplained to the reported precision, and check totalA minus totalB equals observedDelta. A reported balances:true whose own numbers do not reconcile is a fail, and so is a balanceResidual that is non-zero or absent. EVERY ROW IS ACCOUNTED FOR: every nonzero segment remainder is NAMED, including when opposing gaps sum to zero — broken down in unexplainedBySegment with amounts that sum to unexplained and a row count behind it — so the owner is told where the gap lives, not merely that it exists. A term with no executable predicate, or a residual bucket named `other`, `timing`, `misc` or `rounding` counted as explained, is an automatic fail: those rows are unexplained by definition. DISCREPANCIES ARE QUANTIFIED, NOT HIDDEN: totals, term amounts and deltas are reported at full precision rather than rounded to a headline figure, every measure carries its declared tolerance and a withinTolerance verdict COMPUTED from the comparison rather than asserted, and a withinTolerance:true whose unexplained exceeds its tolerance — or a verdict that contradicts its own numbers — is a fail. PER SIDE the report carries real denominators: checkedA and checkedB are both greater than zero and on the order of their source's declared size at the shared grain (a measure 'agreed' over 0 rows on either side is a fail), rows excluded as null, unjoinable or un-rollable are reported with their count and their amount rather than absorbed, and grain uniqueness is reported for both sides. Both negative controls report detected:true with the exact injected change and segment. Compare each controlled residual with the original residual: their difference must equal the injection. Every explained term must remain unchanged. Detection does not require crossing the owner tolerance; report withinTolerance according to the actual policy even when a control stays within it. If sources.scanned is 'sample', both sides state their sample size and method and no delta is presented as a full-population fact. Segment labels and examples respect the safe-use boundary. Fail if the primary evidence came from the seeded control rather than the declared sources. Include the most consequential finding for the business in findings. Every count carries its denominator in plain words.\nRead both negativeControls: drop-keys and alter-segment. Inspect the actual programs to verify the SAME equations run on real and copied sources. Control detection is the change from the original residual, not a pre-existing gap. Verify no term absorbs the injection. Decimal strings preserve exact amounts; do not demand binary floating-point numbers. Do not require one aggregate unexplained total across unlike measures."},
		sdkworkflow.Node{ID: "owner-review", Kind: "check", Title: "Review the answer and remaining gaps", Instruction: "Judge this as the analyst who has to stand in the room on Thursday and say which dashboard is right and why. PASS only if: both sources were profiled at the declared shared grain with real totals and a grain-uniqueness check; every measure the brief named is either reconciled or explicitly listed as unexpressible; every term of every equation is a named filter with an executable predicate, and nothing is absorbed into a residual bucket; every approved equation was executed against the full declared sources with real per-side counts; the accounting balances arithmetically and the per-segment deltas sum to the total delta; every nonzero segment remainder is named, even when opposite gaps cancel in the total; the tolerance verdicts follow from the numbers and the tolerance the owner declared before measurement rather than from a tolerance moved to fit; and the seeded discrepancy was actually caught as unexplained. FAIL if the reconciliation is reassuring rather than true: a gap explained by a term nobody can execute, a 'timing difference' with no rows behind it, deltas rounded until they look like noise, an unexplained remainder with no location, totals compared across two different grains or over a non-unique key, two differently-drawn samples compared as populations, equations quietly missing from the report, a control that does not detect its injected change from the original residual, a blocker measure outside tolerance while the summary reads as agreement, or a segment label that leaks what the safe-use boundary forbids. Name the single most consequential thing this reconciliation says — the number the owner must act on — and the weakest term in the accounting. REVIEW SCOPE: judge ONLY against the declared context contract (the CONTEXT block: source A, source B, the shared grain, the measures and their definitions, the tolerance, the known differences, safe-use). FAIL only when a declared-contract item is unproven or contradicted by the artifacts: a declared measure neither reconciled nor declared unexpressible, an equation not executed, accounting that does not balance, an unexplained remainder left unnamed, a verdict contradicting its own counts, a control that does not detect its injected change from the original residual, or a safe-use breach. Concerns OUTSIDE the declared contract — measures nobody asked to reconcile, fixing the upstream job that caused the gap, which dashboard should be retired, monitoring that would be nice to have — are advisory findings: include them in findings, but do NOT fail the gate for them. The human outcome decision, not this gate, weighs findings. Include the most consequential finding for the business in findings. Every count carries its denominator in plain words.\nControls must detect their injected residual change from baseline in each operation, not necessarily breach owner tolerance. Never sum different units into one gap. Preserve cancelling segment discrepancies."},
		sdkworkflow.Node{ID: "summary", Kind: "document", Title: "Explain the discrepancy and next actions", Instruction: "Return standalone Markdown. The markdown must cover, in order: THE ANSWER TO THE DECLARED QUESTION — the brief carries the question this reconciliation was commissioned to answer, in the words the meeting will ask it, and the first paragraph answers THAT question in those words; where the brief declared what each dashboard shows today, say whether this run reproduced each figure (quoting both the declared figure and the one computed here, at full precision, with the as-of date each covers) before explaining any difference, because a reconciliation that cannot get back to the number in the room has not started explaining it; then the headline — do the two dashboards agree at the declared grain, within the tolerance the owner declared, yes or no per measure, in one sentence each; THE EQUATION, written out per measure with real numbers at full precision (`net_revenue: A 41,882,140.57 = B 44,315,902.13 − filter:internal-accounts 612,405.22 − filter:intercompany 1,504,880.19 + filter:post-snapshot-closes 402,118.44 − filter:refunds-netted 718,594.59 + unexplained 0.00`), stated first because it is the part a reader cannot reconstruct from anywhere else, each term with the rows it selects and the side that applies it; the PER-SEGMENT DELTA TABLE (segment, measure, A, B, delta, explained, unexplained, tolerance verdict) with a stated note that the segment deltas sum to the total delta; the VERDICT PER MEASURE against the declared tolerance, with the tolerance quoted and where it came from; WHAT REMAINS UNEXPLAINED in its own section — the amount, the segments carrying it, the rows behind it, and what it would take to close it — or the sentence that nothing does, because 'unexplained: 0.00' is the claim this whole document exists to support; which number answers which question, so a reader knows which dashboard to quote for what; the measures that could not be reconciled and why; and the limits — what this reconciliation did NOT check, and specifically that agreeing at the declared grain proves the two dashboards are consistent with each other, never that either number is the RIGHT number for the business question. Every figure in the document must be traceable to the executed report: quote it at the precision it was computed at, and name the rows behind it. Respect the safe-use boundary in every segment label and example. Carry the reviewer's most-consequential finding forward verbatim rather than smoothing it over; a summary that reads as agreement while a blocker measure sits outside its tolerance is a false report. STYLE CONTRACT — this document is read by people who were not in the run, so it is held to an editorial standard (personas/quinn-tech-editor.md): Write for a first-time reader. Lead with what happened and what to do next — the verdict in sentence one, never sentence four. Active voice; a named actor for every action. One idea per sentence. Define every term of art on first use. Every number carries its unit and denominator. Preserve every caveat and uncertainty — clarity never softens a finding. The test: a reader who was not present can restate what this workflow tried to do, what happened, and what to do next after one read. EXPLAIN ANY NUMBER THAT APPEARS IN TWO DIFFERENT FINDINGS: when the same figure shows up under two findings, say in one clause why it is the same number — a shared denominator, one population counted twice, or a genuine coincidence — because a reader who spots it and is not told assumes one of the two findings is a copy of the other. DISPLAY PRECISION: show percentages and points at two decimals, and where you shorten a value say that the scorecard carries it in full. HAND-OVER: the brief names how this report is handed over — a format and a recipient reference. Address the report to that recipient in its opening line and deliver it in that format. When the brief says the hand-over is unspecified, address it to nobody in particular: invent neither a recipient nor a format, because a document addressed to a guess is worse than one addressed to no one.\nReturn a standalone Markdown report, not a JSON wrapper. Explain both control operations and their change from the original unexplained amount. Preserve per-segment disagreements even when the total agrees. Keep measures with different units separate. Prepare handover files but do not send or publish."},
		sdkworkflow.Node{ID: "summary-review", Kind: "check", Title: "Review the final explanation", Instruction: "READABILITY IS PART OF THE DELIVERABLE — judge this document as a technical editor would, not as its author. PASS only if all five hold. (a) OPENING: the first two sentences state what this workflow attempted AND what the outcome was; a verdict that first appears in sentence three or later is a FAIL, however well written. (b) NO UNDEFINED JARGON: every term of art and every abbreviation is defined at first use, inside this document, without needing the run that produced it — quote each undefined term in findings. (c) NUMBERS CARRY THEIR MEANING: every quantitative claim states its unit AND its denominator; a bare count, a bare percentage, or a rate with no population is a FAIL — quote each offending number. (d) READER-RESTATEMENT TEST: Use the restatement field for your own single-sentence account of what the workflow tried to do, what happened, and what the reader should do next, using ONLY this document. If you cannot write that sentence from this document alone, or it would be wrong, that is the FAIL and the missing piece is the finding. A pass with an empty restatement is not a pass. (e) CAVEATS SURVIVE: every caveat, limit, uncertainty and failed or partial check carried by the upstream verdicts and reports still appears here at its original strength — a caveat softened, generalised or dropped to improve flow is a falsification and a FAIL. Rigor outranks readability where they collide. Quote the offending passage in findings for every failure so the repair knows exactly what to rewrite. Include the most consequential finding for the business in findings. Every count carries its denominator in plain words."},
	)
}
